// ═══════════════════════════════════════════════════════════
// CONFIGURATION
// ═══════════════════════════════════════════════════════════
const cfg = {
    python:     env.get('SDI_PYTHON')      || 'python',
    script:     env.get('SDI_EMA_SCRIPT')  || 'ema_export_to_json.py',
    export:     env.get('SDI_EMA_EXPORT')  || '',
    scenario:   env.get('SDI_EMA_SCENARIO') || '',
    aasUrl:     env.get('SDI_AAS_URL')     || 'http://localhost:8081',
    submodelId: env.get('SDI_AAS_DATASOURCES_ID')
                || 'localhost/demo/aas/Kugelschreiber_TracePEN/DataSources'
};

if (!cfg.export) {
    node.error('SDI_EMA_EXPORT has to point at the export file of the simulation', msg);
    return null;
}
flow.set('cfg', cfg);

msg.payload = '"' + cfg.python + '" "' + cfg.script + '" "' + cfg.export + '"'
            + (cfg.scenario ? ' "' + cfg.scenario + '"' : '');
node.status({ fill: 'blue', shape: 'dot', text: 'reading export' });
flow.set('emaExport', env.get('SDI_EMA_EXPORT'));
node.log('Simulation export: ' + env.get('SDI_EMA_EXPORT'));
return msg;

// ═══════════════════════════════════════════════════════════
// Evaluate the simulation data and assign it to the openLCA processes.
//
// The export names operations, openLCA keeps one process per part with an
// energy parameter. The assignment sits here and is the only place that
// has to be touched when the production sequence changes.
// ═══════════════════════════════════════════════════════════
const MONTAGE_PROZESS   = '5c609b0a-d929-4789-9024-e3dc11aff29f';
const MONTAGE_PARAMETER = 'Energieverbrauch_Montage_Kugelschreiber';

// The simulation covers the assembly: the robot arm placing the parts and
// the final inspection. Its energy therefore belongs in full to the
// assembly process of the pen.
//
// The energy of manufacturing the individual parts (bolt, sleeve, pen tip)
// is not simulated. It is measured at the machines and comes in through
// the data source "Manufacturing".
// Refill, spring and screw are purchased parts and carry no energy of
// their own for now.
const ZUORDNUNG = {};   // empty = every operation goes to the assembly

if (msg.payload === undefined || msg.payload === '') {
    node.error('The evaluation script produced no output', msg);
    return null;
}
// Depending on its content the exec node hands the output over as text or
// as a buffer. A buffer does not pass the test for a string and would be
// passed on unread - the flow then reported an empty file although the
// script had done its work properly.
let roh = msg.payload;
if (roh && typeof roh === 'object' && typeof roh.toString === 'function'
        && !Array.isArray(roh) && roh.length !== undefined) {
    roh = roh.toString('utf8');
}

let daten;
try {
    daten = typeof roh === 'string' ? JSON.parse(roh) : roh;
} catch (e) {
    node.error('The output of the evaluation script is not JSON: ' + String(roh).slice(0, 200), msg);
    return null;
}

const ops = daten.operations || [];
if (ops.length === 0) {
    // What the script delivered belongs in the message - otherwise an empty
    // file cannot be told apart from a call that failed.
    node.error('The export holds no operations. Read from: '
    + (flow.get('emaExport') || env.get('SDI_EMA_EXPORT') || '(no path set)')
    + '. For a relative path, start Node-RED through start-nodered.ps1, '
    + 'which resolves it.', msg);
    return null;
}

const ohneZuordnung = [];
ops.forEach(op => {
    const z = ZUORDNUNG[op.operationNumber];
    op.lcaProcessId = z ? z.prozess : MONTAGE_PROZESS;
    op.lcaParameterName = z ? z.parameter : MONTAGE_PARAMETER;
});
if (ohneZuordnung.length > 0) {
    node.warn('Operations without an openLCA assignment: ' + ohneZuordnung.join(', '));
}

const summe = ops.reduce((s, o) => s + (o.energyPerUnitMJ || 0), 0);
flow.set('sim', {
    scenario: daten.scenario || '',
    exportFile: (flow.get('cfg').export || '').split(/[\\/]/).pop(),
    operations: ops,
    totalEnergyMJ: summe,
    retrievedAt: new Date().toISOString()
});
node.log(ops.length + ' operations, ' + summe.toFixed(6) + ' MJ per piece');

// Load the DataSources submodel
const cfg = flow.get('cfg');
const b64 = Buffer.from(cfg.submodelId, 'utf8').toString('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
flow.set('submodelB64', b64);
msg.method = 'GET';
msg.url = cfg.aasUrl + '/submodels/' + b64;
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
flow.set('emaExport', env.get('SDI_EMA_EXPORT'));
node.log('Simulation export: ' + env.get('SDI_EMA_EXPORT'));
return msg;

// ═══════════════════════════════════════════════════════════
// MAPPING simulation -> AAS
// Target: DataSources submodel -> SML "DataSources" -> SMC "Simulation"
// ═══════════════════════════════════════════════════════════
const sim = flow.get('sim');
const sm = msg.payload;

if (!sm || !Array.isArray(sm.submodelElements)) {
    node.error('The DataSources submodel could not be read', msg);
    return null;
}

function idShort(str) {
    let s = String(str || '')
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
        .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue').replace(/ß/g, 'ss')
        .replace(/[^A-Za-z0-9_]/g, '_').replace(/__+/g, '_').replace(/_+$/, '');
    if (!/^[a-zA-Z]/.test(s)) { s = 'AG_' + s; }
    return s.substring(0, 128) || 'Undefined';
}
const prop = (id, v, t) => ({ modelType: 'Property', idShort: id,
    valueType: t || 'xs:string', value: v === null || v === undefined ? '' : String(v) });
const smc = (id, v) => ({ modelType: 'SubmodelElementCollection', idShort: id, value: v });
const byId = (arr, id) => (arr || []).find(e => e && e.idShort === id);

const belegt = {};
const prozesse = sim.operations.map(op => {
    let id = idShort(op.operationNumber + '_' + op.operationName);
    if (belegt[id]) { belegt[id] += 1; id = id + '_' + belegt[id]; } else { belegt[id] = 1; }
    return smc(id, [
        prop('OperationNumber', op.operationNumber),
        prop('OperationName', op.operationName),
        prop('WorkStation', op.workstation),
        prop('CycleTime', op.cycleTimeSeconds, 'xs:double'),
        prop('CycleTimeUnit', 's'),
        prop('ProcessDuration', op.processingTimeHours, 'xs:double'),
        prop('ProcessDurationUnit', 'h'),
        prop('EnergyPerUnit', op.energyPerUnitMJ, 'xs:double'),
        prop('EnergyPerUnitUnit', 'MJ'),
        prop('LCAProcessId', op.lcaProcessId),
        prop('LCAParameterName', op.lcaParameterName)
    ]);
});

const simValue = [
    prop('DataSource', 'Simulation'),
    prop('SourceSystem', 'ema Plant Designer'),
    prop('TimeOfSimulation', sim.retrievedAt, 'xs:dateTime'),
    prop('Scenario', sim.scenario),
    prop('ExportFile', sim.exportFile),
    prop('TotalEnergyPerUnit', sim.totalEnergyMJ, 'xs:double'),
    prop('TotalEnergyPerUnitUnit', 'MJ'),
    smc('SimulationProcesses', prozesse)
];

let list = byId(sm.submodelElements, 'DataSources')
        || byId(sm.submodelElements, 'Data Sources')
        || sm.submodelElements.find(e => e.modelType === 'SubmodelElementList');
if (!list) {
    node.error('SubmodelElementList "DataSources" not found', msg);
    return null;
}
if (!Array.isArray(list.value)) { list.value = []; }

const pos = list.value.findIndex(e => e && e.idShort === 'Simulation');
const neu = smc('Simulation', simValue);
if (pos >= 0) { list.value[pos] = neu; node.log('Simulation updated'); }
else { list.value.push(neu); node.log('Simulation newly created'); }

msg.method = 'PUT';
msg.url = flow.get('cfg').aasUrl + '/submodels/' + flow.get('submodelB64');
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = sm;
node.status({ fill: 'blue', shape: 'dot', text: 'writing AAS' });
return msg;

// Ergebnis melden
const sim = flow.get('sim') || {};
if (msg.statusCode && msg.statusCode >= 400) {
    node.error('AAS-Schreibvorgang fehlgeschlagen: HTTP ' + msg.statusCode, msg);
    node.status({ fill: 'red', shape: 'ring', text: 'HTTP ' + msg.statusCode });
    return null;
}
msg.payload = {
    status: 'ok', dataSource: 'Simulation', scenario: sim.scenario,
    operations: (sim.operations || []).length,
    totalEnergyMJ: sim.totalEnergyMJ, exportFile: sim.exportFile
};
node.status({ fill: 'green', shape: 'dot',
              text: (sim.operations || []).length + ' Arbeitsgaenge' });
node.log('Simulationsdaten in AAS geschrieben');
return msg;
